// === Tab: mySketch ===
/**
 * video from
 * https://www.pexels.com/video/wide-angle-shot-of-a-bonfire-in-the-snow-6603134/
 */

let vmin, vmax;
let ctx;
let pg, gl, glsl, pgScale = 10;
let triUvTex, triStrokeTex;
let NUM = 14, step, radius;
let triArr = [];
let video;

let vertexShader = `
attribute vec3 aPosition;
attribute vec2 aTexCoord;
attribute vec3 aNormal;
uniform mat4 uProjectionMatrix;
uniform mat4 uModelViewMatrix;
varying vec2 vTexCoord;

void main() {
  vTexCoord = aTexCoord;
  vec4 position = vec4(aPosition, 1.0);
  gl_Position = uProjectionMatrix * uModelViewMatrix * position;
}`;

let fragmentShader = `
precision mediump float;
varying vec2 vTexCoord;
uniform sampler2D uTex;
uniform sampler2D uUvTex;

void main() {
  vec2 uv = texture2D(uUvTex, vTexCoord).xy;
  vec3 tex = texture2D(uTex, uv).rgb;
  gl_FragColor = vec4(tex, 1.0);
}`;

function setup() {
  createCanvas(1112, 834, WEBGL);
  // createCanvas(800, 800, WEBGL);
  gl = drawingContext;
	glsl = createShader(vertexShader, fragmentShader);
  vmin = max(width, height);
  vmax = max(width, height);
  pg = createGraphics(540, 540);
  triUvTex = createGraphics(vmax, vmax);
  triStrokeTex = createGraphics(vmax, vmax);

  video = createVideo(['https://openprocessing.org/sketch/1441152/files/fire.mp4'], () => {
    video.loop();
  });
  video.hide();

  step = vmax / (NUM - 1);
  radius = (step / 2) / (3 / 2);

  let r = radius;
  for (let l = 0; l <= NUM + 1; l++) {
    let y = l * (r * 3 * cos(PI / 6));
    for (let k = 0; k < NUM; k++) {
      let x = k * step;
      if (l % 2 === 1) {
        x += step / 2;
      }
      for (let j = 0; j < 6; j++) {
        let A = j * TWO_PI / 6;
        let cx = x + cos(A) * r;
        let cy = y + sin(A) * r;
        for (let i = 0; i < 3; i++) {
          let i2 = (i + 1) % 3;
          let a1 = i * TWO_PI / 3 + A + PI;
          let v1 = createVector(cx + cos(a1) * r, cy + sin(a1) * r);
          let a2 = i2 * TWO_PI / 3 + A + PI;
          let v2 = createVector(cx + cos(a2) * r, cy + sin(a2) * r);
          triArr.push({
            v0: createVector(cx, cy),
            v1,
            v2
          });
        }
      }
    }
  }

  // uv texture
  for (let { v0, v1, v2 } of triArr) {
    let vx = (v0.x + v1.x + v2.x) / 3;
    let vy = (v0.y + v1.y + v2.y) / 3;
    let u = map(vx, 0, triUvTex.width, 0, 255);
    let v = map(vy, 0, triUvTex.height, 0, 255);
    triUvTex.fill(u, v, 0);
    triUvTex.stroke(u, v, 0);
    triUvTex.beginShape(TRIANGLES);
    triUvTex.vertex(v0.x, v0.y);
    triUvTex.vertex(v1.x, v1.y);
    triUvTex.vertex(v2.x, v2.y);
    triUvTex.endShape();
  }

  // stroke texture
  triStrokeTex.noFill();
  triStrokeTex.stroke(255, 16);
  for (let { v0, v1, v2 } of triArr) {
    var vx = (v0.x + v1.x + v2.x) / 3;
    var vy = (v0.y + v1.y + v2.y) / 3;
    triStrokeTex.beginShape(TRIANGLES);
    triStrokeTex.vertex(v0.x, v0.y);
    triStrokeTex.vertex(v1.x, v1.y);
    triStrokeTex.vertex(v2.x, v2.y);
    triStrokeTex.endShape();
  }
}

function draw() {
  let sec = millis() / 1000;
  let s = sin(sec) * 0.5 + 0.5;

  pg.image(video, 0, 0, pg.width, pg.height);

  background(0);

  noStroke();
  push();
  {
    shader(glsl);
    glsl.setUniform('uTex', pg);
    glsl.setUniform('uUvTex', triUvTex);
    plane(vmax, vmax);
  }
  pop();

  gl.enable(gl.BLEND);
  gl.blendFunc(gl.SRC_ALPHA, gl.ONE);

  push();
  {
    texture(triStrokeTex);
    plane(vmax, vmax);
  }
  pop();
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  } 
}

